arguments.command:
python3 -c "
import json
print(repr(json.loads('1e400')))
try:
    print(json.loads('1'+'0'*5000))
except Exception as e: print('huge int err:', type(e).__name__, str(e)[:80])
def pc(x): raise ValueError('nonfinite '+x)
try:
    json.loads('{\"a\":NaN}', parse_constant=pc)
except Exception as e: print('nan:', type(e).__name__)
print(repr(json.loads('[1,2]')))
try:
    json.loads('')
except Exception as e: print('empty:', type(e).__name__)
try:
    json.loads('{\"a\":01}')
except Exception as e: print('leading zero:', type(e).__name__)
"
